using ExamRosterApp.Application; using ExamRosterApp.Domain; using Microsoft.EntityFrameworkCore;
namespace ExamRosterApp.Infrastructure;
public class ExamRosterDbContext:DbContext{public ExamRosterDbContext(DbContextOptions<ExamRosterDbContext> o):base(o){} public DbSet<Teacher> Teachers=>Set<Teacher>(); public DbSet<ExamDutySlot> ExamDutySlots=>Set<ExamDutySlot>(); public DbSet<DutyAssignment> DutyAssignments=>Set<DutyAssignment>(); public DbSet<TeacherUnavailableSlot> TeacherUnavailableSlots=>Set<TeacherUnavailableSlot>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<Teacher>().HasData(new Teacher{Id=1,FullName="Alice"},new Teacher{Id=2,FullName="Bob"},new Teacher{Id=3,FullName="Carla",CanWorkAfternoon=false}); b.Entity<ExamDutySlot>().HasData(new ExamDutySlot{Id=1,Date=new DateOnly(2026,6,1),StartTime=new TimeOnly(9,0),EndTime=new TimeOnly(11,0),ShiftType=ShiftType.Morning,Grade="10",Subject="Math",Venue="Hall A",TeachersRequired=2},new ExamDutySlot{Id=2,Date=new DateOnly(2026,6,1),StartTime=new TimeOnly(13,0),EndTime=new TimeOnly(15,0),ShiftType=ShiftType.Afternoon,Grade="10",Subject="Science",Venue="Hall B",TeachersRequired=1});}}
public class EfRepository:IAppRepository{private readonly ExamRosterDbContext _db; public EfRepository(ExamRosterDbContext db){_db=db;} public Task<List<Teacher>> GetTeachersAsync()=>_db.Teachers.ToListAsync(); public Task<List<ExamDutySlot>> GetSlotsAsync()=>_db.ExamDutySlots.ToListAsync(); public Task<List<TeacherUnavailableSlot>> GetUnavailableAsync()=>_db.TeacherUnavailableSlots.ToListAsync(); public Task<List<DutyAssignment>> GetAssignmentsAsync()=>_db.DutyAssignments.ToListAsync(); public async Task SaveAssignmentsAsync(IEnumerable<DutyAssignment> a){await _db.DutyAssignments.AddRangeAsync(a);} public async Task ClearAssignmentsAsync(){_db.DutyAssignments.RemoveRange(_db.DutyAssignments); await Task.CompletedTask;} public Task SaveChangesAsync()=>_db.SaveChangesAsync();}
